def maximumKToSortPermutation(nums):
    n = len(nums)
    if nums == sorted(nums):
        return 0  # Already sorted

    # For k from the max possible (n-1) down to 0
    for k in range(max(nums), -1, -1):
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[py] = px

        # Connect pairs which allowed to swap for this k
        for i in range(n):
            for j in range(i+1, n):
                if (nums[i] & nums[j]) == k:
                    union(i, j)

        # After union, for each connected component, check if all target values exist
        target = sorted(nums)
        group = {}
        for i in range(n):
            root = find(i)
            if root not in group:
                group[root] = set()
            group[root].add(nums[i])

        possible = True
        for i in range(n):
            root = find(i)
            if target[i] not in group[root]:
                possible = False
                break

        if possible:
            return k

    return 0
